class AsyncQueue<T> {
  private items: T[] = []; private waiters: Array<() => void> = [];
  async push(item: T): Promise<void> { this.items.push(item); this.waiters.shift()?.(); }
  async *drain(): AsyncGenerator<T> {
    while (true) {
      while (!this.items.length) await new Promise<void>(r => this.waiters.push(r));
      yield this.items.shift()!;
    }
  }
}
