const jobs: ReadableStream<Job> = new ReadableStream({
  async pull(controller) {
    const next = await source.next();          // called when demanded
    next.done ? controller.close() : controller.enqueue(next.value);
  },
}, new CountQueuingStrategy({ highWaterMark: 256 }));

for await (const job of jobs) await handle(job);
